import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(1)
    ch.send(7)
    let v = ch.receive()
    let n: Int64 = 5
    match v {
        Some(n) => { let _ = 0 }
        None => { let _ = 0 }
    }
    if n == 5 {
        io.println("five")
    } else {
        io.println("notfive")
    }
    return Ok(())
}
